INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '拓展', 3, '{"stem": "学校要为体育老师购置运动服。商场促销：上衣145元/件，裤子158元/条。学校共6位体育老师，每人一套，怎么买最便宜？\n促销规则：满2套优惠20元/套；满6套优惠30元/套；满8套优惠40元/套。", "options": null}', '方案：买6套（含6套优惠30元/套）共1638元最便宜。', '每套原价 145+158=303（元）；满6套优惠：6×(303−30)=6×273=1638（元）；单买：145×6+158×6=870+948=1818（元）。1638<1818，满6套优惠最便宜。', 'paper', '["practice", "ykl3sx", "2.8"]', NULL, 0);

