INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '选择', 3, '{"stem": "□25×○，○表示同一个数字。当○=（ ）时，这个乘法算式的积是一个整百数，而且是一个四位数。A.0  B.2  C.4  D.6", "options": null}', 'C', '○=4 时：125×4=500（整百三位 ✗）；250×4=1000（整百四位 ✓）；500×4=2000（整百四位 ✓）；750×4=3000（整百四位 ✓）。所以 ○=4 → 选 C。', 'paper', '["practice", "ykl3sx", "2.8"]', NULL, 0);
